INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trivia for Dummies', 'The official Trivia For Dummies multiple choice trivia game. Trivia For Dummies is party gaming at it''s very best, in an easy out of the box, pick-up-and-play game that will keep everyone at the edge of their seat. Jam packed with over 6,500 multiplechoice trivia questions in seven genre categories, no game will be the same. Trivia For Dummies is a fun way of spending quality time with friends and family and of all ages.' FROM games WHERE igdb_id = 187456 ON CONFLICT (game_id, language_code) DO NOTHING;
