INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pareicopse', 'Surviving the night in the woods should be easy, as long as you don''t wander too far away from camp... Pareicopse is a survival horror experience where you''re tasked with finding your camping buddy who has been gone a little too long. Navigate the woods, and stay hidden from things bumping in the night. This game was made for the Haunted PS1 game jam in a little over a month, and released for Halloween.' FROM games WHERE igdb_id = 323598 ON CONFLICT (game_id, language_code) DO NOTHING;
