INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gem Raider 2', 'Gem Raider 2 is an old-school move-and-shoot game. Your objective in each room is to destroy all of the Power Gems and return to the teleport pad to exit. Other Gems can also be destroyed to increase your score. There are 20 rooms and each of the 9 types of enemy Gems has unique weapons or skills.' FROM games WHERE igdb_id = 188467 ON CONFLICT (game_id, language_code) DO NOTHING;
