INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TaiWord: A Daily Word Game', 'Welcome to TaiWord. A fun new daily word game! Every day you must solve the 5, 7 and 10 letter anagrams - You are against the clock, how fast can you solve them? You also can play Multi TaiWord, a brand new mode where you have 5 minutes to guess as many words from 8 letters! With 10 leaderboards, see if you are fastest everyday or if you have the best TaiWord streak! TaiWord is a fun way to train your brain but also learn new words with definitions for each word!' FROM games WHERE igdb_id = 232039 ON CONFLICT (game_id, language_code) DO NOTHING;
