INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'OS: Memories', 'OS: Memories is a short and engaging storyline about the everyday life of a game developer. It offers an immersive experience through an old computer interface, allowing players to relive Andy''s life story and uncover his deepest deadlocks. The game includes puzzles that provide insights into difficult situations and encourages players to explore Andy''s personal archives and memories.' FROM games WHERE igdb_id = 188787 ON CONFLICT (game_id, language_code) DO NOTHING;
