INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Devilish Contract', 'You follow the story of a boy who lacks self-confidence. He can''t even muster up the courage to ask a girl out. One day, he happens to find a book in the attic. He decides to open the dark and suspicious book and inside, he finds a spell that can "grant any wish." He reads the spell out loud and a puff of black smoke spews from the book. Out of the smoke, a demon appears.' FROM games WHERE igdb_id = 279670 ON CONFLICT (game_id, language_code) DO NOTHING;
