INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Redactle', 'Redactle is a daily browser-based puzzle game where the user tries to determine the subject of a random obfuscated Wikipedia article, chosen from Wikipedia''s 10,000 Vital Articles. Type in words to reveal them on the page. Figure out the article title to win. New puzzle daily at 11:00 am CDT (16:00 UTC).' FROM games WHERE igdb_id = 197384 ON CONFLICT (game_id, language_code) DO NOTHING;
