INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mahjong Business Style', 'Become a business shark – play Mahjong on the exchange! Complete more than 100 levels, earning points and countless trophies. Each pack embodies a separate market – from stocks to advanced technologies—and each level contains special high-value gold pieces to collect! Enjoy classic levels or challenge yourself with levels that include wandering pieces, in which the arrangement of the tokens changes with each new attempt! Climb the ladder of success and Wall Street will bow to you!' FROM games WHERE igdb_id = 195013 ON CONFLICT (game_id, language_code) DO NOTHING;
