INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Black Death: A Tragic Dirge', 'Nothing is as it seems in the Medieval world of Black Death. Find sanctuary in this eerie town that does not exist on any of the maps you have seen before. The Black Death is horrible plague that drives its victims insane and causes extreme paranoia. It has infected most of this town’s residents and seeks to claim your sanity too.' FROM games WHERE igdb_id = 212718 ON CONFLICT (game_id, language_code) DO NOTHING;
