INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tearstone: Thieves of the Heart - Collector''s Edition', 'The Heart of Tearstone has gone missing! Ten years have passed since your last journey into this strange world, and with the Heart’s disappearance, powerful sorcery has taken hold! With few clues to follow, your quirky troop of friends has summoned you to help solve a growing mystery and save the inhabitants of Tearstone! Who took the Heart? What secrets does it contain? … And is this airship actually safe? There’s only one way to find out! Climb aboard and hold on tight for a challenging and enchanting Hidden Object Puzzle Adventure game for the ages!' FROM games WHERE igdb_id = 322791 ON CONFLICT (game_id, language_code) DO NOTHING;
