INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rain Ruin', 'FPS walking simulator type psychological horror game. Lost in the mountains and sheltering from the rain in her ruins, she had no choice but to reveal her night in the ruins. As she relies on her smartphone''s lights to explore the pitch-black ruins, she hears a cry out of nowhere.' FROM games WHERE igdb_id = 207358 ON CONFLICT (game_id, language_code) DO NOTHING;
