INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dungeons-of-shalnor', 187480, '2022-01-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4e8l.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1d27.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeons of Shalnor', '"An Eye for Immortality… What a terrible price to pay for such a terrible curse!" Dungeons of Shalnor is a tactical Roguelike game. It features a Turn-Based combat along with a "Turn the camera" mechanic that also turns all monsters and projectiles, causing interesting outcomes such as: Monsters walking into traps; or attacking one another. Find powerful Artifacts and Blessings in each dungeon run. With the right combination, you might even feel like a god. There are many different types of monsters, and each move and behave differently in puzzle-like patterns. Every time you die, your gold is transformed into Ghost Coins, which can be used to purchase permanent Upgrades in the Spirit Shop. The game uses a Half-Procedural generation method to create random encounters but also familiar scenes.' FROM games WHERE igdb_id = 187480 ON CONFLICT (game_id, language_code) DO NOTHING;
