INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chaste Tris', 'Chaste Tris is my first complete video game I have made. It is obviously based on similar other games but easier because there is no gravity. Blocks can be freely moved up, down, left, and right with the arrow keys. They can be rotated with X or Y keys and can also be held for later use with C.' FROM games WHERE igdb_id = 202615 ON CONFLICT (game_id, language_code) DO NOTHING;
