INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tree Hole: Adventures In Wonderland', 'While exploring a cave you come across a tree with a magical hole in it. The hole draws you in and everything goes black. Waking up confused about the past events you find out that you ended up in some sort of magical town in which some of its citizens mysteriously disappeared. What happened to the citizens, how can you find your way home and how is all this connected. Your adventure starts now.' FROM games WHERE igdb_id = 248191 ON CONFLICT (game_id, language_code) DO NOTHING;
