INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Heardle', 'A variation of Heardle dedicated to songs from throughout the entire Mario franchise. This includes not only Super Mario and its spinoffs, but the Donkey Kong, Yoshi, Wario, Luigi''s Mansion, Princess Peach, and Captain Toad games as well. Mario remixes from the Super Smash Bros. and Mario & Sonic at the Olympic Games series are also included. Originally created with glitch.com but has since moved to GitHub.' FROM games WHERE igdb_id = 203820 ON CONFLICT (game_id, language_code) DO NOTHING;
