INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Die drei???: Plan der Chamäleonbande', 'A wave of sophisticated robberies is keeping the whole country on tenterhooks. The well-camouflaged "Chameleon Gang" is said to be behind it. Strangely enough, the places and times of the burglaries coincide with the tour schedule of a popular singing duo. Are the musicians behind the crimes? Bob goes along on tour and investigates undercover. But where are Justus and Peter?' FROM games WHERE igdb_id = 302665 ON CONFLICT (game_id, language_code) DO NOTHING;
