INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rental Chan', 'Racheal works for an app called Rent-A-Friend. She gets paid for being friends with people for a limited time. She needs money to pay for her little sister''s hospital bills who is being treated for a rare disease. When a rare opportunity comes up, a family is worried about their daughter and is willing to pay Rachael a large sum of money to transfer schools and befriend with until the end of the school year.' FROM games WHERE igdb_id = 228823 ON CONFLICT (game_id, language_code) DO NOTHING;
