INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('flying-umbrella', 213494, '2022-08-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5o7h.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1sov.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flying Umbrella', '"Flying Umbrella" - 2d platformer game about a girl who moves in different directions with every gust of wind. Learn to control your body. The bus won''t wait long. Collect berries, only carefully flying around traps and wild animals. Everything will work out!' FROM games WHERE igdb_id = 213494 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 213494 AND ge.slug = 'indie' ON CONFLICT DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 213494 AND p.igdb_id = 6 ON CONFLICT DO NOTHING;
